fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome70 {
    data class Success(val payload: String) : Outcome70()
    data object Failure : Outcome70()
}

fun describe70(outcome: Outcome70): String = when (outcome) {
    is Outcome70.Success -> outcome.payload
    Outcome70.Failure -> "failed"
}
@JvmName("step71")
fun step71(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 6
}
data class Pair72<A, B>(val first: A, val second: B)

fun combine72(left: Int, right: Int): Pair72<Int, Int> {
    return Pair72(left + 13, right + 19)
}
